    pub(crate) async fn updated(
        &self,
        changed: &[String],
        deleted: &[String],
        roots: Option<&[String]>,
    ) -> Result<Rpc, CallError> {
        let changes = Changes {
            file_notifications: (!changed.is_empty() || !deleted.is_empty())
                .then_some(FileNotifications { changed, deleted }),
            reconfigure_programs: roots
